import 'package:flutter/material.dart';
class HomeScreen extends StatelessWidget { final bool showBuildLabel; final String localProfileId; const HomeScreen({super.key,required this.showBuildLabel,required this.localProfileId}); @override Widget build(BuildContext context){ final shortId=localProfileId.length<=8?localProfileId:localProfileId.substring(0,8); return Scaffold(appBar:AppBar(title:const Text('Reise mit Worten')),body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Reise mit Worten'),if(showBuildLabel)...[const SizedBox(height:8),const Text('Foundation Build 0.2'),Text('Local profile: $shortId…')]]))); } }
